mapper.insert:
INSERT INTO `document_version` (
    document_id, version_number, file_id, content_hash, extracted_text,
    parse_status, change_summary, created_by_user_id, created_at
) VALUES (
    #{documentId}, #{versionNumber}, #{fileId}, #{contentHash}, #{extractedText},
    #{parseStatus}, #{changeSummary}, #{createdByUserId}, #{createdAt}
)

mapper.update:
UPDATE `document_version`
SET
    extracted_text = #{extractedText},
    parse_status = #{parseStatus}
WHERE id = #{id}

mapper.select:
SELECT id, document_id, version_number, file_id, content_hash, extracted_text,
       parse_status, change_summary, created_by_user_id, created_at
FROM `document_version`
WHERE document_id = #{documentId}
  AND version_number = #{versionNumber}
LIMIT 1
